// High-quality official promotional and stage production artwork
export const SHOW_WATERMARKS: Record<string, string> = {
  'lion-king': 'data:image/svg+xml;base64,',
  'together-pixar': 'data:image/jpeg;base64,',
  'mickey-magician': 'data:image/svg+xml;base64,',
  'stars-parade': 'data:image/svg+xml;base64,',
  'tales-of-magic': 'data:image/svg+xml;base64,',
  'cascade-lights': 'data:image/svg+xml;base64,',
  'doctor-strange': 'data:image/jpeg;base64,',
  'alice-bmx': 'data:image/jpeg;base64,',
  'dream-factory': 'data:image/svg+xml;base64,',
};

export function getShowWatermark(name: string): string | undefined {
  const lower = name.toLowerCase();
  if (lower.includes('lion king') || lower.includes('roi lion')) return SHOW_WATERMARKS['lion-king'];
  if (lower.includes('together') || lower.includes('pixar')) return SHOW_WATERMARKS['together-pixar'];
  if (lower.includes('magicien') || lower.includes('magician') || lower.includes('mickey')) return SHOW_WATERMARKS['mickey-magician'];
  if (lower.includes('stars on parade') || lower.includes('parade')) return SHOW_WATERMARKS['stars-parade'];
  if (lower.includes('tales of magic') || lower.includes('château') || lower.includes('nocturne')) return SHOW_WATERMARKS['tales-of-magic'];
  if (lower.includes('cascade of lights') || lower.includes('cascade') || lower.includes('lake') || lower.includes('lac')) return SHOW_WATERMARKS['cascade-lights'];
  if (lower.includes('fabrique') || lower.includes('dream factory') || lower.includes('disney junior')) return SHOW_WATERMARKS['dream-factory'];
  if (lower.includes('doctor strange') || lower.includes('strange') || lower.includes('avengers')) return SHOW_WATERMARKS['doctor-strange'];
  if (lower.includes('alice') || lower.includes('reine de c') || lower.includes('queen of hearts')) return SHOW_WATERMARKS['alice-bmx'];
  return undefined;
}
